def write_html():
    cards=''.join(f'<section class="group" id="group-{g["id"]}"><div class="group-head"><h2>{g["id"]} / {esc(g["title"])}</h2><p>{esc(g["description"])}</p></div><div class="state-grid">'+''.join(state_card(f) for f in g['frames'])+'</div></section>' for g in GROUPS)
    source_json=json.dumps({'groups':GROUPS,'sha':SHA,'repository':REPO},ensure_ascii=False).replace('</','<\/')
    page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>OutLoud · Complete app wireframe · PR31</title><style>{CSS}</style></head><body>
<header><div class="eyebrow">OutLoud / Team 07 / Source-derived wireframes</div><h1>The complete rehearsal loop.</h1><p class="intro">All seven implemented screens, with {len(FRAMES)} wireframes for their main views, overlays, and major states. Follow the numbered links between frames; select any phone to inspect its behavior and exact source.</p><div class="meta"><span><strong>Source</strong> <a href="{REPO}/pull/31">PR #31</a> / <a href="{REPO}/tree/{SHA}">{SHA[:7]}</a></span><span><strong>Snapshot</strong> 17 October 2026 · Asia/Seoul</span><span><strong>Coverage</strong> 7 screens / {len(FRAMES)} wireframes / 9 groups</span></div></header>
<div class="toolbar"><nav aria-label="Diagram sections"><a href="#overview">Map</a>{''.join(f'<a href="#group-{g["id"]}">{g["id"]} {esc(g["title"].split(" & ")[0])}</a>' for g in GROUPS)}</nav><div class="tool-actions"><a href="outloud-pr31-wireframe.pdf">PDF</a><a href="outloud-pr31-wireframe.svg">Full SVG</a><button id="all-notes" aria-pressed="false">Show source notes</button></div></div>
<main><section class="overview" id="overview"><div class="kicker">01 / Navigation</div><h2>One app. Seven screens.</h2><p>Home is the presentation library. Setup, playback, corrections, assessments, and saved Q&A are nested views within this navigation. Text in brackets is a wireframe placeholder; charts and waveforms are schematic.</p>{route_map()}<div class="route-notes"><div><strong>Record → review → improve</strong><span>The first saved take opens Full Review. Later saved takes open Slide Review. A redo can first open Compare; Keep current or Overwrite resolves the selected recording.</span></div><div><strong>Return paths keep their context</strong><span>Full Review returns to Home, slides, or Slide Review according to where it opened. Slide Review returns to Full Review when opened there. Q&A returns to Slide Review.</span></div><div><strong>Read the board as a state diagram</strong><span>A–I groups contain all 54 numbered wireframes. Links beneath each frame identify real actions and their destinations. Different scroll positions and overlays are shown separately. VARIANTS means conditional messages or controls, displayed one at a time.</span></div></div><ul class="index">{''.join(f'<li><a href="#{f["id"]}">{f["id"]} · {esc(f["title"])}</a></li>' for f in FRAMES)}</ul></section>
{cards}<div class="footnote">Reconstructed from the pinned source rather than generated app screenshots. Source files and a full state inventory accompany this diagram. A connected Galaxy S23 Ultra was observed on Review; the installed build’s exact PR revision was not established. No application code, installed build, recordings, provider jobs, or remote repository content was changed. Reading source describes implemented behavior; it does not prove every state has been exercised on a device.</div></main>
<dialog id="focus"><div class="focus-head"><div><div class="kicker" id="focus-tag"></div><h2 id="focus-title"></h2></div><button id="focus-close" aria-label="Close wireframe details">Close</button></div><div class="focus-grid"><div class="focus-phone" id="focus-phone"></div><div class="focus-content" id="focus-content"></div></div></dialog>
<script type="application/json" id="wireframe-data">{source_json}</script>
<script>
const data=JSON.parse(document.getElementById('wireframe-data').textContent), frames=data.groups.flatMap(g=>g.frames), byId=Object.fromEntries(frames.map(f=>[f.id,f])), focus=document.getElementById('focus');
const safe=s=>String(s).replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function showFrame(id){{const f=byId[id];if(!f)return;document.getElementById('focus-tag').textContent=f.id+' / '+f.kind+' / '+f.screen;document.getElementById('focus-title').textContent=f.title;document.getElementById('focus-phone').innerHTML=document.querySelector('#'+f.id+' svg').outerHTML;document.getElementById('focus-content').innerHTML='<ul>'+f.notes.map(n=>'<li>'+safe(n)+'</li>').join('')+'</ul><div class="kicker">Transitions</div><div class="hops">'+f.transitions.map(t=>'<a href="#'+safe(t.to)+'" data-jump="'+safe(t.to)+'">'+safe(t.label)+' → '+safe(t.to)+'</a>').join('')+'</div><div class="kicker">Pinned source</div><div class="source">'+f.sources.map(s=>'<a target="_blank" rel="noreferrer" href="'+data.repository+'/blob/'+data.sha+'/'+s.path+'#L'+s.line+'">'+safe(s.path)+':'+s.line+'</a>').join('<br>')+'</div>';if(!focus.open)focus.showModal();}}
document.addEventListener('click',e=>{{const b=e.target.closest('[data-focus]');if(b)showFrame(b.dataset.focus);const j=e.target.closest('[data-jump]');if(j&&focus.open)focus.close();}});
document.getElementById('focus-close').onclick=()=>focus.close();focus.addEventListener('click',e=>{{if(e.target===focus){{const r=focus.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)focus.close();}}}});
document.getElementById('all-notes').onclick=e=>{{const open=e.currentTarget.getAttribute('aria-pressed')!=='true';document.querySelectorAll('.state-notes').forEach(d=>d.open=open);e.currentTarget.setAttribute('aria-pressed',String(open));e.currentTarget.textContent=open?'Hide source notes':'Show source notes';}};
</script></body></html>'''
    (OUT/'source-wireframe-board.html').write_text(page)

def write_poster():
    width=1840; group_h=840; height_total=1020+len(GROUPS)*group_h+80
    svg=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height_total}" viewBox="0 0 {width} {height_total}" font-family="Arial,sans-serif"><title>OutLoud PR31 full app wireframe: 54 frames across all 7 screens</title><desc>Source-derived complete navigation and numbered wireframe states. Bracketed values are placeholders; chart shapes are schematic.</desc>',rect(0,0,width,height_total,PAPER,'none',0)]
    svg+=[txt(55,52,'OUTLOUD / TEAM 07 / PR #31 / '+SHA[:7],16,ACCENT),txt(55,110,'Complete app wireframe',43,INK,500),txt(55,144,f'7 implemented screens · {len(FRAMES)} connected wireframes · 17 October 2026',19,MUTED),txt(55,175,'Source-backed screen structure. Bracketed text, chart bars and waveforms are placeholders.',15,MUTED)]
    nav=route_map().replace('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1300 555"','<svg x="55" y="200" width="1730" height="740" viewBox="0 0 1300 555"')
    svg.append(nav)
    svg.append(txt(55,977,'Each frame shows one screen, overlay or scroll state. Follow the action → frame ID links; consult source-wireframe-board.html for behavior and source.',15,MUTED))
    for gi,g in enumerate(GROUPS):
        yy=1020+gi*group_h
        svg.append(f'<line x1="55" y1="{yy}" x2="1785" y2="{yy}" stroke="{INK}"/>')
        svg.append(txt(55,yy+39,g['id']+' / '+g['title'],24,INK,500))
        svg.append(txt(55,yy+65,g['description'],13,MUTED))
        for fi,f in enumerate(g['frames']):
            x=55+fi*290; y=yy+92
            svg.append(f'<g id="{f["id"]}">')
            badge='VARIANTS' if f.get('variants') else f['kind'].upper()
            svg.append(txt(x,y,f['id']+' / '+badge+' / '+f['screen'],11,ACCENT))
            svg.append(words(x,y+21,f['title'],31,14,INK,2))
            card=phone(f).replace('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 452"',f'<svg x="{x}" y="{y+48}" width="260" height="452" viewBox="0 0 260 452"')
            svg.append(card)
            ty=y+519
            for t in f['transitions']:
                parts=lines(t['label']+' → '+t['to'],43,2)
                svg.append(f'<a href="#{esc(t["to"])}">'+''.join(txt(x,ty+j*14,tline,11,MUTED) for j,tline in enumerate(parts))+'</a>');ty+=len(parts)*14+2
            svg.append('</g>')
    svg.append(txt(55,height_total-31,f'Pinned source: {REPO}/tree/{SHA} · Implementation-derived diagram, not device-test evidence.',12,MUTED))
    svg.append('</svg>')
    poster=''.join(svg)
    ET.fromstring(poster)
    (OUT/'outloud-pr31-wireframe.svg').write_text(poster)
    (OUT/'navigation.svg').write_text(route_map())

def validate():
    assert len(FRAMES)==54 and len(BY_ID)==54
    assert len(GROUPS)==9 and all(len(g['frames'])==6 for g in GROUPS)
    assert set(f['screen'] for f in FRAMES)=={'home','upload','rehearse','review','full','compare','qa'}
    for f in FRAMES:
        assert f['sources'] and f['notes'] and f['blocks']
        for s in f['sources']:
            text=source_text(s['path'])
            assert 1<=s['line']<=len(text.splitlines()), s
        for t in f['transitions']:
            assert t['to'] in BY_ID,(f['id'],t)
        assert sum(height(b) for b in f['blocks'])<600, f['id']
    return {'frames':len(FRAMES),'groups':len(GROUPS),'screens':sorted(set(f['screen'] for f in FRAMES)),
            'source_references':sum(len(f['sources']) for f in FRAMES),'transitions':sum(len(f['transitions']) for f in FRAMES),
            'head_sha':SHA,'source_check':'All paths and one-based line references resolve in pinned archive.' if SOURCE is not None else 'All paths and one-based line references resolve in pinned local Git source.'}

if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source-root', type=Path, default=os.environ.get('PR31_SOURCE_ROOT'), help='PR31 archive root; defaults to the pinned commit in local Git.')
    args=parser.parse_args()
    SOURCE=args.source_root.expanduser().resolve() if args.source_root else None
    result=validate();write_html();write_poster()
    (OUT/'validation.json').write_text(json.dumps(result,indent=2)+'\n')
    print(json.dumps(result))
